    super.onCreate(b); final long up=SystemClock.uptimeMillis(); if(b==null&&Build.VERSION.SDK_INT>=31) getWindow().getDecorView().getViewTreeObserver().addOnPreDrawListener(new ViewTreeObserver.OnPreDrawListener(){ public boolean onPreDraw(){ if(SystemClock.uptimeMillis()-up<SPLASH_MS)return false; getWindow().getDecorView().getViewTreeObserver().removeOnPreDrawListener(this); return true; } }); if(b==null&&Build.VERSION.SDK_INT>=31) new Handler(Looper.getMainLooper()).postDelayed(()->getWindow().getDecorView().invalidate(),SPLASH_MS+10); e = new Engine(this); st=new Store(this); sp = getSharedPreferences("cal", 0); ui=getSharedPreferences("ui",0);
    dark=true; bg=0xFF021B29; card=0xFF043349; fg=0xFFF2F0EA; mu=0xFF9DB6C3; ac=0xFFFF803A;
