  protected void onNewIntent(Intent i){ super.onNewIntent(i); setIntent(i); go(i); }
  protected void onPause(){ super.onPause(); if(tab.equals("feel"))stop(); tick.removeCallbacksAndMessages(null); }
  protected void onResume(){ super.onResume(); SyncJob.schedule(this); if(tab.equals("home")&&sub==null)show("home"); else if(inSub&&onSync)syncPage(syncBack); }
  public void onBackPressed(){ if(!back())super.onBackPressed(); }
  Set<String> picked; // drives chosen on History, or null when not choosing
  boolean back(){ if(picked!=null&&sub==null){ picked=null; show("analysis"); return true; } if(sub!=null){ Runnable r=sub; sub=null; r.run(); return true; } if(!tab.equals("home")){ show("home"); return true; } return false; }
