  void page(Runnable up,String title){ if(!inSub)pos.put(tab,sv.getScrollY()); inSub=true; onSync=false; act.setVisibility(View.GONE); foot.setVisibility(View.GONE); list.removeAllViews(); status=null; sub=up; sv.scrollTo(0,0); top(title,true); }
  LinearLayout bar;
