  ImageButton icon(int res,String what,Runnable r){ ImageButton b=new ImageButton(this); b.setImageResource(res); b.setColorFilter(ac); b.setBackground(ripple(new ColorDrawable(0))); b.setContentDescription(what); b.setOnClickListener(v->{ tap(v); r.run(); }); bar.addView(b,new LinearLayout.LayoutParams(dp(48),dp(48))); return b; }
