  /** Drives of a car that pass the date and phone position choices on Analysis. */
  List<JSONObject> matching(JSONObject c){ int dr=ui.getInt("dr",0),ap=ui.getInt("ap",0); long from=since(dr); List<JSONObject> l=new ArrayList<>(); for(JSONObject m:st.list()) if(m.optString("car").equals(c.optString("id"))&&!m.optBoolean("recording")&&m.optLong("start")>=from&&(ap==0||m.optString("place").equals(PLACES[ap-1]))&&how(m,ui.getInt("ah",0)))l.add(m); return l; }
  Dsp sum(JSONObject c,int[] n,int at) throws Exception { Dsp d=new Dsp(); for(JSONObject m:matching(c)) try{ d.add(Dsp.load(st.driveDir(m.getString("id")))); n[at]++; }catch(Exception x){ Log.w("BUZZLAB","skip "+m.optString("id")+" "+x); } return d; }

  // ---------- export and import
  void export(List<JSONObject> ds){ StringBuilder s=new StringBuilder(); for(JSONObject m:ds)s.append(m.optString("id")).append(','); expIds=s.toString(); new AlertDialog.Builder(this).setTitle("Include where you drove?").setMessage("Positions show your routes and home. Speed is always included, and the stats don't need positions.").setPositiveButton("Leave out",(d,w)->pick(false)).setNegativeButton("Include",(d,w)->pick(true)).show(); }
  boolean expFull;
  void fullExport(){ new AlertDialog.Builder(this).setTitle("Full export").setMessage("Everything on this phone: all drives with positions and marks, cars with plates, calibration and the sync log. The server password is left out. Keep the file private.").setPositiveButton("Export",(d,w)->{ expFull=true; expIds=""; startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/zip").putExtra(Intent.EXTRA_TITLE,"buzzlab-full-"+new SimpleDateFormat("yyyy-MM-dd-HHmm",Locale.UK).format(new Date())+".zip"),3); }).setNegativeButton("Cancel",null).show(); }
  Map<String,String> extras(){ Map<String,String> x=new LinkedHashMap<>(); try{ JSONObject c=new JSONObject(); for(Map.Entry<String,?> e:sp.getAll().entrySet())c.put(e.getKey(),e.getValue()); x.put("calibration.json",c.toString(1)); x.put("app.json",new JSONObject().put("version",lv()).put("server",ui.getString("url","")).put("exported",System.currentTimeMillis()).toString(1)); x.put("sync-log.txt",ui.getString("syncLog","")); }catch(Exception e){ Log.w("BUZZLAB","extras "+e); } return x; }
